sys_variable_value.value:
(function() {
    var planGr = new GlideRecord('x_1919740_dayone_0_onboarding_plan');
    planGr.initialize();
    planGr.setValue('employee_name', 'ATF Safe Handling');
    planGr.setValue('employee_id', 'ATF-015');
    planGr.setValue('state', 'active');
    // No joining_date set
    var planId = planGr.insert();

    var taskGr = new GlideRecord('x_1919740_dayone_0_onboarding_task');
    taskGr.initialize();
    taskGr.setValue('plan', planId);
    taskGr.setValue('task_name', 'Task Without Date Context');
    taskGr.setValue('mandatory', true);
    taskGr.setValue('task_state', 'open');
    taskGr.setValue('department', 'it');
    taskGr.insert();

    // This should not throw
    var engine = new DayOneReadinessEngine(planId);
    engine.recalculate();

    planGr = new GlideRecord('x_1919740_dayone_0_onboarding_plan');
    planGr.get(planId);
    var score = parseInt(planGr.getValue('readiness_score'), 10);
    var forecast = planGr.getValue('forecast_status');

    if (score !== 0) throw new Error('Score should be 0, got ' + score);
    if (forecast !== 'no_joining_date') throw new Error('Forecast should be no_joining_date, got ' + forecast);
    gs.info('T-15 PASSED: Engine handled missing data safely. Score=' + score + ' Forecast=' + forecast);
})();
